Output120The above function can be written as a tail-recursive function. The idea is to use one more argument and accumulate the factorial value in the second argument. When n reaches 0, return the accumulated value.
            C++

    #include <iostream>
using namespace std;

// A tail recursive function to calculate factorial
unsigned factTR(unsigned int n, unsigned int a)
{
    if (n <= 1)
        return a;

    return factTR(n - 1, n * a);
}

// A wrapper over factTR
unsigned int fact(unsigned int n) { return factTR(n, 1); }

// Driver program to test above function
int main()
{
    cout << fact(5);
    return 0;
}


